import{_ as e,c as a,o as t,ah as _}from"./chunks/framework.BxT5r71R.js";const l=JSON.parse('{"title":"音乐商业革命续篇：BMSG的日本复兴计划","titleTemplate":"Management 2 本篇","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/Management2/PART3/15_音乐商业革命续篇：BMSG的日本复兴计划.md","filePath":"zh-cn/Management2/PART3/15_音乐商业革命续篇：BMSG的日本复兴计划.md"}'),n={name:"zh-cn/Management2/PART3/15_音乐商业革命续篇：BMSG的日本复兴计划.md"};function S(M,p,r,s,B,o){return t(),a("div",null,[...p[0]||(p[0]=[_('<p>演讲</p><p>► 2024年7月25日｜摘自日经Cross Trend FORUM 2024</p><h2 id="音乐商业革命续篇-bmsg的日本复兴计划" tabindex="-1">音乐商业革命续篇：BMSG的日本复兴计划 <a class="header-anchor" href="#音乐商业革命续篇-bmsg的日本复兴计划" aria-label="Permalink to &quot;音乐商业革命续篇：BMSG的日本复兴计划&quot;">​</a></h2><p><strong>2024年7月25日，SKY-HI（日高光启）登台参加日经Cross Trend FORUM 2024，演讲主题为“音乐商业革命续篇：BMSG的日本复兴计划”。他于2020年创办的BMSG已大幅成长，如今旗下拥有2组组合、5名个人艺人。BE:FIRST在出道仅2年4个月时便成功举办了巨蛋演出。掌舵BMSG的SKY-HI表示，进军全球市场的“准备已经就绪”。为什么要在此时走向世界？本次访谈将解读BMSG的未来构想。（采访人：吾妻拓，《日经Cross Trend》编辑委员）</strong></p><p>——过去一年，BMSG的公司规模进一步扩大，旗下艺人也增加了。目前有2组组合、5名个人艺人、3名练习生（trainee）……</p><p>把艺人照片这样摆在一起，就会发现这几位个人艺人风格迥异，真是太棒了，没有谁和谁的气质一样。BMSG的名字来自Be MySelf Group，我们的宗旨就是营造一个环境，艺人和其他伙伴都能在其中保持真实的自我。光看照片，就能感受到BMSG的特色。</p><p>不过，我也觉得，过去一年里，这些各具个性的人之间，似乎逐渐形成了BMSG特有的氛围和风格。前些天，艺人们来我演出的后台，看着他们相处得那么融洽、开心，我就想，今后也一定要珍惜这样的关系和氛围。</p><p>——4月，您公布了新愿景“TYOISM（东京主义）”，宣布将以东京为基地，进军全球音乐市场。您在介绍这一愿景时说“时机已经成熟”，这句话令人印象深刻。</p><p>确实就是“时机已经成熟”。更准确地说，是每位艺人都已经打下了各自坚实的基础。当然，在与国内外各方交流的过程中，我也越来越能感受到BMSG这家公司的影响力，业务合作能够进入实质推进阶段的机会也多了很多。打个比方，一位在冲绳活动的艺人，随着媒体曝光增加，也在东京租了房子。我们的情况与此相似：我们以东京为基地开展活动，如今无论是创作作品，还是推广作品，都开始更具体地考虑海外市场。我想，我们已经进入了这样的阶段。</p><p>——“世界”从公司成立之初就是关键词之一，如今终于进入了现实视野。</p><p>是的，从一开始，世界就一直是我们的目标，只是现在变得具体了。我想，原本作为“目标”的事情，如今已经成了业务自然延伸的一部分。比如，亚洲一些当下颇受关注、风格有趣的艺人向我们发来合作邀约；我们主动提出合作，也有人愿意参与。可以说，从东京向世界传播音乐，我们在各方面都已经做好了准备。</p><p>对我们来说，明确加上“从东京出发”这几个字很重要。与其说是地理上的东京，不如说是作为文化概念的东京。日本是个岛国，也曾经历数百年的锁国时期，孕育了独特的文化。这当然有利也有弊，尤其是日本音乐行业，有时会遭到“加拉帕戈斯化”的揶揄（编者注：借加拉帕戈斯群岛物种独立演化的特点，比喻产业在相对封闭的市场中独自发展，形成鲜明特色，也可能与国际市场脱节）。不过，加拉帕戈斯群岛的象龟，不也很有意思吗？同样，日本音乐也确实走出了独特的演化路径。我想保留这样的特色。或许还谈不上“日本自古传承的文化”，但我想有意识地用“东京”这个概念，承载日本特有的文化观念。</p><p>——BMSG在日本国内已经汇聚了一批人气艺人，规模也在不断扩大。能否请您再谈谈，为什么仍然必须走向海外？</p><p>道理很简单。一个原因是，娱乐是最典型的面向消费者（toC）的业务，不是吗？所以，我们非常希望接触更多受众，把作品传播得更广。单从梦想来说，我们就想走得更远。当然，赢得东京都大赛也很了不起，但既然要参赛，还是想赢得全国大赛吧。我们的目标也是如此。另一个原因是危机感。我想，各行各业都面临这个问题。光看人口结构就很清楚，日本的人口会不断减少。过去内需充裕，如今外资在这个市场中占据的份额却越来越大。用“抢夺”或“被抢走”来谈娱乐，总觉得不太合适，措辞确实有些为难。但纯粹从产业角度看，日本音乐产业本就面临市场日益萎缩的前景，外资占据的份额还在不断扩大。</p><p>刚才照片里的练习生大约17岁。就算他们从现在开始从事艺人活动，20年后的2044年，也才和现在的我差不多年纪。想到他们20年后的处境，我觉得，如果只着眼于日本国内，生活恐怕会很艰难。他们可能不得不兼做其他工作。照此发展下去，整个日本娱乐产业甚至更有可能成为韩国娱乐产业的外包承接方——韩国娱乐产业已经具备全球影响力。如果现在不切实开拓海外销售渠道，往后连应当守护的文化也会守不住。我觉得，这样的征兆已经出现了不少。</p><p>不过，事情复杂的地方在于：好的作品，无论来自哪个国家，都是好的。就像我们想把作品推向海外一样，海外的好作品也会进入日本。这一点，我想先说清楚。正因为作品好，这种流动恐怕无法阻挡，也没有必要阻止，更不应该阻止。不过，我们绝对有能力做出质量足以与之匹敌的作品。所以，我们必须认真做好作品，不断创造走出去的条件，把整个地球都当作自己的主场，不是吗？</p><p>我们是艺人管理公司，我自己也作为制作人，负责他们所有歌曲的制作。但我们不能只管把歌做好，还应该考虑怎样把音乐送到听众面前。这些，我们也算是在考虑了，比如在合适的时机举办巡演。不过，我之所以说“也算是在考虑”，是有原因的。个别艺人通过演唱动画主题曲等方式，在海外积累粉丝，再到当地演出，这样的例子过去就有，尤其最近越来越多。但要说以组织为单位，有系统地把音乐本身输出到海外，我认为日本还没有真正做到。我们必须创造这样的成功案例。我也觉得，这是一个极其艰巨的课题。</p><p>——过去也有许多艺人怀着在海外发展的愿望走出去，但真正形成大规模业务的案例极少。就目前而言，您认为需要解决哪些问题？</p><p>我认为主要有两点。第一，是壮大进军海外的组织力量。当然，BMSG自身也必须成长，但还需要与其他经纪公司等伙伴携手，以拓展海外受众为目标，形成更大的合作组织。国家也一直有意支持内容出口，不是吗？虽然至今未必取得了切实成果，但始终表达着支持的意愿。我认为，有必要把这些力量也纳入其中，壮大组织。别说个人，单靠一家公司，能做的事也有极限。我们需要树立共同走出去的意识，在日本全国范围内形成更大的合作组织。</p><p>第二，是“坚持下去”。如今互联网发达，信息传播虽然不再有时间差，实践中却仍会出现偏差。开展市场营销、模拟推演、做出好作品、付诸实践，再检验结果——不断重复这个过程。最初三四年里，很可能还是守着日本内需市场更容易做好生意。但即便如此，如果不坚持拓展海外，10年、20年后就会吃苦头。</p><p>即使是现在已经出道的艺人，如果10年、20年后才40岁，那之后的人生还很长，不是吗？以BE:FIRST、MAZZEL这样的唱跳组合为例，这种表演形态首先会在20多岁时迎来一次巅峰。即使30多岁还在继续，表演也会与20多岁时不同。到了40多岁，又会是另一番样貌。</p><p>可人生还会继续，还有50多岁、60多岁、70多岁。因此，如何趁现在开足马力，非常重要。如今每位艺人都精力充沛，趁着这股劲头还在，包括我在内的成年人必须为他们找准方向。大家要乐观开朗、和睦相处、充满活力，同时也要不断进取，一起努力。</p><p>不过，BMSG是一家新公司，从一开始就以世界为目标，所以即使初期亏损，我们也能接受。比如，在海外活动半年后，销售额比上一年有所下降，但这是有意义的尝试，评估成果时就要把这一点考虑进去。历史悠久或规模庞大的公司，确实更难进行这样的尝试。所以我认为，这正是我们这样的创业公司应该做的事。</p><p>——与全球其他市场相比，日本音乐市场的流媒体用户相对较少。您之前也提到，要走向世界，这也是必须加强的一个方面。</p><p>日本音乐行业曾经白白浪费了20年：对互联网过度担忧，始终排斥它、限制它……当时，作为艺人的我，对此除了愤慨，还是愤慨。日本至今依然落后，这是事实。但增加流媒体平台的流量，海外销售渠道就会随之打开吗？也没有那么简单。不过，数字摆在那里，日本艺人确实容易给人留下“没什么人听”的印象。这在现阶段严重拖了后腿。但这也不过是冰山一角，等待解决的问题依然堆积如山。</p><p>而且，也不是传播得广就行。举个极端的例子，为了吸引海外观众，给一部忍者动画唱主题曲时，所有人都穿成忍者的样子，也许会受到美国观众欢迎。但到了下一部作品，又不得不说“还得继续扮一阵子忍者”，这样真的幸福吗？努力争取更多受众时，不能忘记：把作品传递出去固然重要，以什么方式传递也同样重要。这种时候，需要的或许正是“质量优先”“创意优先”“艺人优先”。艺人首先要确立自己想要呈现的样子，忠于本来的自己，然后再多做尝试。跳过这个前提，一切就失去了根本。应该先有这个基础，再考虑能做些什么，不是吗？</p><p>流媒体很重要，用起来也方便、有趣。但如果粉丝使用它，不是为了自己享受音乐，而是为了支持艺人、帮助艺人拓展海外市场，我又觉得有些本末倒置。这也是我的两难之处。我想，或许只有坚持“质量优先”“创意优先”“艺人优先”，才可能逐渐改变行业和社会的氛围。</p><p>——BMSG在挑战海外市场的过程中，想必还要跨越各种障碍。那么，对于本次主题所说的“通过娱乐重振日本”，BMSG是如何考虑的？</p><p>正因为音乐是最典型的toC业务，它才能与所有产业建立联系。如今到亚洲各国，从抵达机场的那一刻起，就能看到韩国产品的广告牌，还有代言这些产品的K-POP偶像，不是吗？对音乐以外的产业来说，外需也非常重要，而娱乐产业越兴盛，外需也会随之不断扩大。就像三星、LG成长为大型企业一样，其他企业也可以与娱乐产业共同壮大。我认为，两者是相互关联的。</p><p>娱乐产业兴盛，整个国家也会更有活力，所以我认为经济一定会好转。反过来，娱乐直接面向消费者，一旦经济不景气，人们的可支配收入减少，娱乐消费就会受到影响。因此，这几年行业一直处境艰难。</p><p>娱乐产业发展起来，也会带动其他产业，整个社会的信心也会提升。我认为，产业出口与娱乐密不可分。</p><p>——从这个角度来看，BMSG在BE:FIRST的《Masterplan》CD发行上也做了新的尝试，希望推动娱乐产业持续发展。具体是怎样的尝试呢？</p><p>虽然前面已经说过，但我想再强调一下：娱乐存在的意义，就是带来快乐，说到底，就是给人活力。发行《Masterplan》这张单曲时，我们通过改用纸质封套等方式，大幅减少了塑料用量；同时取消收藏卡等随机特典，购买1张CD就能拿到全体成员的收藏卡。另外，过去各销售门店还有不少专属特典，我们也取消了。</p><p>回归商业的本质，是《Masterplan》这张单曲的理念之一。促使顾客勉强自己大量购买CD，最后那些CD根本没人听，就被丢掉——我一直认为，这种不健康的模式绝不可能长久，整个行业也会因此衰败。问题是谁来迈出这一步，而这正是我创业时就下定决心要做的事情之一。我们把过去作为特典赠送的周边商品改为单独销售。结果，CD销量比上一张减少了约7万张，塑料用量减少了10吨，相当于一只霸王龙的重量。换算成用电量，相当于给手机充满电1200万次。单靠一个人，大概怎么也做不到吧。但仅仅发行一张单曲，就实现了这样的减量。而且，周边商品改为单独销售后，销售额增至约2倍。我们也能给予艺人更多收益回报，所以我认为，这次尝试是成功的。</p><p>不过，仅由某一艺人或组合在发行作品时这样做，即使减少了相当于一只霸王龙重量的塑料，也仍然是杯水车薪。真正应该做的，是改变社会的整体氛围。如果主流制作方式也随之逐渐转向，不仅会对环保产生非常积极的影响，在商业层面，无论是粉丝的消费方式，还是艺人的收益回报，我认为都会得到显著改善。</p><p>比如，为CD购买者举办特典活动，偶像们就要忙上一整天。这期间不能上课训练，也不能唱歌，却要不停说话，直到口干舌燥。一整天下来，本人获得的收益分成比例还很低，结果成了只有版权方赚钱。我既是版权方，也是艺人管理公司的社长，如今由我来推动这项改革，希望大家能从中感受到我的迫切心情。不过，我相信，只要长期坚持，行业氛围一定会逐渐改变。</p><p>我们真的必须为更多人带来幸福。不能只因为某样东西能赚钱、能做成生意，就一股脑儿往海外输出。我真心认为，我们绝不能停止探索，必须不断寻找更好的方式，为偶像、艺人以及支持他们的人带来尽可能多的幸福。一直沿用至今的商业模式，不可能一下子彻底改变，不是吗？我觉得，慢慢来就可以。但眼下绝对有必要做的，是不再非黑即白，而是大家一起朝着无限接近白色的灰色努力。我相信，在善与恶之间，社会一定会逐渐走向善的一方，所以我想继续努力。</p><p>——明白了。那么，BMSG接下来会怎么做？</p><p>前些天，大家一起开了BMSG FES的筹备会议，各位艺人不断提出自己想做的事。我觉得，这样的环境非常好，希望能一直保持下去。艺人说“我想做这个”，公司就有支持他们实现想法的环境。这会直接影响他们的创造力，以及表演时的动力和状态。我想，这应该是最重要的。</p><p>说到底，今天谈了很多具体问题，也谈了娱乐产业的商业层面。但如果要用一句话概括今后要做什么，那就是支持每位艺人追求自己真正喜欢的东西、自己想成为的样子，并且始终坚持下去。我觉得，归根结底就是这一点。</p><p>有一种观念认为，做偶像就必须压抑自己，舍弃许多普通人理应享有的东西。我想，BMSG或许正站在这种观念的对立面。更加忠于自己，坚持“Be MySelf”，也就是“做自己”，究竟有多美好——我相信，无论哪个国家的人，都能感受到其中的美好和快乐，所以我会继续努力。</p><p>——最后，请您再说几句。</p><p>我们当然珍视艺人和偶像的幸福，但不止于此。我们承诺，会通过娱乐，不断创造作品，丰富所有支持者的人生。来自其他行业的各位，如果也能意识到娱乐产业中蕴藏着发展的机会与契机，我会非常高兴。娱乐产业确实蕴藏着机遇，能够推动各行各业发展壮大。希望我们携起手来，一起努力。</p>',43)])])}const c=e(n,[["render",S]]);export{l as __pageData,c as default};
